1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	
4	const BASE_PREMIUM: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	  moonstone: 25,
11	};
12	
13	interface Item {
14	  type: string;
15	}
16	
17	interface QuoteStep {
18	  op: "quote";
19	  items: Item[];
20	}
21	
22	interface Scenario {
23	  customer: { yearsWithMHPCO: number };
24	  steps: QuoteStep[];
25	}
26	
27	interface QuoteResult {
28	  premium: number;
29	}
30	
31	interface ScenarioResult {
32	  results: QuoteResult[];
33	}
34	
35	const COMPONENT_BLOCK_SIZE = 3;
36	const COMPONENT_BLOCK_BASE = 60;
37	
38	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
39	
40	const isRuneBlock = (items: Item[]): boolean =>
41	  items.length === COMPONENT_BLOCK_SIZE && items.every((item) => item.type === "rune");
42	
43	const itemsBasePremium = (items: Item[]): number =>
44	  isRuneBlock(items)
45	    ? COMPONENT_BLOCK_BASE
46	    : items.reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
47	
48	const quotePremium = (step: QuoteStep): number => {
49	  const base = itemsBasePremium(step.items);
50	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_RATE;
51	  return roundUpInMHPCOsFavor(base + firstInsuranceSurcharge + PROCESSING_FEE);
52	};
53	
54	export const runScenario = (scenario: Scenario): ScenarioResult => ({
55	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
56	});
