3	
4	describe("MHPCO Claim Office", () => {
5	  // === Simplest cases ===
6	  it("empty item list quote → premium 5 G (only processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	    expect(result).toEqual({ results: [{ premium: 5 }] });
12	  });
13	
14	  // === Base premiums for main items ===
15	  it("quote a plain sword (steel, enchantment 3) → base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
16	    const result = runScenario({
17	      customer: { yearsWithMHPCO: 0 },
18	      steps: [{ op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] }],
19	    });
20	    expect(result).toEqual({ results: [{ premium: 115 }] });
21	  });
22	  it("quote a plain amulet → 60 G base + 6 G first insurance + 5 G fee = 71 G", () => {
23	    const result = runScenario({
24	      customer: { yearsWithMHPCO: 0 },
25	      steps: [{ op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] }],
26	    });
27	    expect(result).toEqual({ results: [{ premium: 71 }] });
28	  });
29	  it("quote a plain staff → 80 G base + 8 G first insurance + 5 G fee = 93 G", () => {
30	    const result = runScenario({
31	      customer: { yearsWithMHPCO: 0 },
32	      steps: [{ op: "quote", items: [{ type: "staff", material: "oak", enchantment: 2, cursed: false }] }],
33	    });
34	    expect(result).toEqual({ results: [{ premium: 93 }] });
35	  });
36	  it("quote a plain potion → 40 G base + 4 G first insurance + 5 G fee = 49 G", () => {
37	    const result = runScenario({
38	      customer: { yearsWithMHPCO: 0 },
39	      steps: [{ op: "quote", items: [{ type: "potion", material: "glass", enchantment: 1, cursed: false }] }],
40	    });
41	    expect(result).toEqual({ results: [{ premium: 49 }] });
42	  });
43	
44	  // === Components ===
45	  it("quote 1 rune → 25 G base + 2.5 G first insurance (rounded up) + 5 G fee = 33 G", () => {
46	    const result = runScenario({
47	      customer: { yearsWithMHPCO: 0 },
48	      steps: [{ op: "quote", items: [{ type: "rune" }] }],
49	    });
50	    expect(result).toEqual({ results: [{ premium: 33 }] });
51	  });
52	  it("quote 2 runes → 50 G base premium (+ modifiers + fee) = 60 G", () => {
53	    const result = runScenario({
54	      customer: { yearsWithMHPCO: 0 },
55	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
56	    });
57	    expect(result).toEqual({ results: [{ premium: 60 }] });
58	  });
59	  it("quote 3 runes → 60 G base + 6 G first insurance + 5 G fee = 71 G", () => {
60	    const result = runScenario({
61	      customer: { yearsWithMHPCO: 0 },
62	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] }],
63	    });
64	    expect(result).toEqual({ results: [{ premium: 71 }] });
65	  });
66	  it("quote 4 runes → 100 G base + 10 G first insurance + 5 G fee = 115 G (no block)", () => {
67	    const result = runScenario({
68	      customer: { yearsWithMHPCO: 0 },
69	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }] }],
70	    });
71	    expect(result).toEqual({ results: [{ premium: 115 }] });
72	  });
73	  it("quote 7 runes → 175 G base + 17.5 first insurance + 5 fee = 197.5 → 198 G rounded up", () => {
74	    const result = runScenario({
75	      customer: { yearsWithMHPCO: 0 },
76	      steps: [{ op: "quote", items: [
77	        { type: "rune" }, { type: "rune" }, { type: "rune" },
78	        { type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" },
79	      ] }],
80	    });
81	    expect(result).toEqual({ results: [{ premium: 198 }] });
82	  });
83	  it("quote 2 runes + 1 moonstone → 75 G base + 7.5 first insurance + 5 fee = 87.5 → 88 G", () => {
84	    const result = runScenario({
85	      customer: { yearsWithMHPCO: 0 },
86	      steps: [{ op: "quote", items: [
87	        { type: "rune" }, { type: "rune" }, { type: "moonstone" },
88	      ] }],
89	    });
90	    expect(result).toEqual({ results: [{ premium: 88 }] });
91	  });
92	  it.todo("quote 3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
93	
94	  // === Item-level modifier: cursed ===
95	  it.todo("quote a cursed sword (steel, enchantment 3), newcomer with 0 years → 165 G (100 base + 50 curse + 10 first insurance + 5 fee)");
96	
97	  // === Item-level modifier: high enchantment ===
98	  it.todo("quote a sword with enchantment 5 → high-enchantment surcharge applies (30 G)");
99	  it.todo("quote a sword with enchantment 4 → no high-enchantment surcharge");
100	  it.todo("quote a cursed sword with enchantment 5 → both surcharges apply");
101	
102	  // === Policy-level modifiers ===
103	  it.todo("quote a sword for a customer with exactly 2 years → loyalty discount applies (20% off policy base)");
104	  it.todo("quote a sword for a customer with 1 year → no loyalty discount");
105	
106	  // === Modifier scope on multi-item policies ===
107	  it.todo("policy with cursed sword and plain amulet → base 160 G; curse adds 50 G (of sword only) → 210 G before fee + first insurance");
108	
109	  // === Rounding in MHPCO's favor ===
110	  it.todo("premium calculation yielding 197.5 G → 198 G (rounded up)");
111	  it.todo("payout calculation yielding 350.5 G → 350 G (rounded down)");
112	
113	  // === Second contract / follow-up ===
114	  it.todo("customer's second quote → 15% follow-up discount applies to policy base");
115	
116	  // === First-insurance surcharge is per item ===
117	  it.todo("long-standing customer's second quote of a cursed sword (enchantment 7) → 160 G total (integration example)");
118	
119	  // === Newcomer integration example ===
120	  it.todo("newcomer cursed sword (steel, enchantment 3) integration example → 165 G");
121	
122	  // === Claims: basic ===
123	  it.todo("claim on regular sword (steel, enchantment 3), damage 500 G → payout 400 G (500 - 100 deductible)");
124	  it.todo("claim on rune (250 G insurance), damage 200 G → payout 100 G (200 - 100 deductible)");
125	
126	  // === Claims: enchantment threshold ===
127	  it.todo("claim on steel sword enchantment 9, damage 1000 G → payout 400 G (50% then -100 deductible)");
128	  it.todo("claim on dragon-material sword enchantment 8, damage 1000 G → payout 400 G (high-enchantment wins, then deductible)");
129	  it.todo("claim on dragon-material sword enchantment 5, damage 800 G → payout 700 G (dragon full, then deductible)");
130	  it.todo("claim on dragon-material sword enchantment 9, damage 1000 G → payout 400 G (50% wins, then deductible)");
131	
132	  // === Deductible per damage event ===
133	  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (100 deductible per item)");
134	
135	  // === Multiple items of same type ===
136	  it.todo("policy with two swords → insurance sum 2000 G, cap 4000 G");
137	  it.todo("dragon attack damages two swords → each entry treated separately with its own deductible");
138	  it.todo("claim with more sword damages than swords insured → CLI error, non-zero exit");
139	
140	  // === Cap and cap exhaustion ===
141	  it.todo("policy with sword and amulet → insurance sum 1600 G, cap 3200 G");
142	  it.todo("cursed sword premium modifiers don't affect cap → cap 2000 G");
143	  it.todo("policy with sword + 3 runes (block) → insurance sum 1750 G");
144	  it.todo("sword insured (cap 2000), first claim 1500 → payout 1400 G, cap remaining 600 G");
145	  it.todo("sword insured (cap 2000), second claim 1500 after first → payout 600 G, cap remaining 0 G");
146	
147	  // === Error cases ===
148	  it.todo("quote with unknown item type (broomstick) → CLI error");
149	  it.todo("claim references item not in policy → CLI error");
150	  it.todo("claim with negative damage amount → CLI error");
151	});
